WITH with_latest AS (SELECT s.id, s.city, s.region, s.opened_date, latest.units FROM stores s LEFT JOIN LATERAL (SELECT c.units FROM store_sales c WHERE c.store_id = s.id ORDER BY c.sale_date DESC, c.id DESC LIMIT 1) latest ON TRUE), eligible AS (SELECT s.* FROM with_latest s WHERE NOT EXISTS (SELECT 1 FROM inventory c WHERE c.store_id = s.id AND c.last_restock < s.opened_date)), remaining_keys AS (SELECT id FROM eligible EXCEPT SELECT id FROM stores WHERE store_name IS NOT NULL), kept_rows AS (SELECT s.* FROM eligible s JOIN remaining_keys k ON s.id = k.id), valid AS (SELECT region, opened_date, units, CAST(units AS DOUBLE) AS units_str FROM kept_rows WHERE region IS NOT NULL) SELECT region, opened_date, RANK() OVER (PARTITION BY region ORDER BY units_str DESC NULLS LAST) AS units_str_rank, CUME_DIST() OVER (ORDER BY units_str ASC NULLS FIRST) AS units_str_cume_dist FROM valid WHERE opened_date <= '2023-12-01'
